INSERT INTO publish_attempt (
    attempt_id, post_id, creator_id, idempotent_key, status, failed_step,
    error_message, fallback_task_type, fallback_target_type, fallback_target_id,
    fallback_failure_reason, fallback_next_retry_at, retry_count, created_at, updated_at
) VALUES (
    #{attemptId}, #{postId}, #{creatorId}, #{idempotentKey}, #{status}, #{failedStep},
    #{errorMessage}, #{fallbackTaskType}, #{fallbackTargetType}, #{fallbackTargetId},
    #{fallbackFailureReason}, #{fallbackNextRetryAt}, #{retryCount}, #{createdAt}, #{updatedAt}
)

mapper.select:
SELECT *
FROM publish_attempt
WHERE creator_id = #{creatorId}
  AND post_id = #{postId}
  AND idempotent_key = #{idempotentKey}
